mapper.select:
SELECT user_id
FROM "USER"
WHERE email = #{email, jdbcType=VARCHAR}

mapper.update:
UPDATE users
SET u_password = #{u_password},
u_nickname = #{u_nickname}
WHERE u_id = #{u_id}

mapper.delete:
DELETE FROM users
WHERE u_id = #{u_id}
AND u_password = #{u_password}

mapper.select:
SELECT COUNT(*)
FROM users
WHERE u_email = #{value, jdbcType=VARCHAR}

SELECT u_id, u_email, u_password, u_nickname
FROM users
WHERE u_email = #{value, jdbcType=VARCHAR}

SELECT cr_id, cr_product_id, cr_seller_id, cr_buyer_id
FROM chat_room
WHERE cr_id = #{roomId}
